// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract Recorder {
    bytes public lastData;
    uint256 public calls;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastData = msg.data;
        calls += 1;
        return true;
    }

    fallback() external payable {
        lastData = msg.data;
        calls += 1;
    }
}

contract InvMutTest is Test {
    EBU c;

    function setUp() public {
        c = new EBU();
    }

    function testFuzz_property(address from, uint256 amount, address recipient) public {
        Recorder rec = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint256[] memory v = new uint256[](1);
        v[0] = amount;

        c.transfer(from, address(rec), tos, v);

        bytes memory expected = abi.encodeWithSelector(
            bytes4(keccak256("transferFrom(address,address,uint256)")),
            from,
            recipient,
            amount
        );

        assertTrue(keccak256(rec.lastData()) == keccak256(expected));
    }
}
